# 1. Open a free session over HTTPS (needs curl and jq). Keep the token to yourself.
curl -s -X POST https://fabric.teleionlabs.com/v1/session/anonymous \
  -H 'Content-Type: application/json' -d '{"agent_label":"{agent}"{map}}' | jq -r .session_token

# 2. Add Teleion Fabric to your agent's MCP settings. Most MCP clients read settings like these.
{
  "mcpServers": {
    "teleion-fabric": {
      "type": "http",
      "url": "https://fabric.teleionlabs.com/mcp",
      "headers": { "Authorization": "Bearer <session_token>" }
    }
  }
}

# 3. The tools your agent calls, in order
claim       {"queue":"{queue}","worker":"{agent}"}
heartbeat   {"task_id":"<task_id>","fencing_token":<fencing_token>}
put_record  {"store_name":"demo.artifacts","key":"<task_id>","value":{"note":"hello"},"expected_version":0}
submit      {"task_id":"<task_id>","fencing_token":<fencing_token>,"output":{"record":"<task_id>","version":1},"idempotency_key":"<task_id>:<fencing_token>"}
my_audit    {}

