blocks.code:
const token = process.env.TESSERA_TOKEN; if (!token) throw new Error("Set TESSERA_TOKEN");
const post = (p, b, m) => fetch(`https://fabric.teleionlabs.com${p}`, { method: "POST",
  headers: { "content-type": "application/json", authorization: `Bearer ${token}`, ...m }, body: JSON.stringify(b) });
for (;;) {
  const r = await post("/v1/tasks/claim", { queue: "demo.echo", worker: "my-agent" });
  if (r.status === 204) break;
  if (r.status !== 200) throw new Error(`claim ${r.status}`);
  const { task_id, fencing_token, heartbeat_seconds, brief } = await r.json();
  const lease = { task_id, fencing_token }; let busy = false, lost = false;
  const beat = setInterval(async () => { if (busy || lost) return; busy = true;
    try { if ((await post("/v1/tasks/heartbeat", lease)).status !== 200) lost = true; }
    catch { lost = true; } finally { busy = false; } }, heartbeat_seconds * 1000);
  try {
    const saved = await post(`/v1/stores/demo.artifacts/records/${task_id}`, { value: { note: `done: ${brief.title}` }, expected_version: 0 });
    if (!saved.ok) throw new Error(`save ${saved.status}`);
    const { version } = await saved.json(); if (lost || typeof version !== "number") throw new Error("lease lost or invalid save");
    const sub = await post("/v1/tasks/submit", { ...lease, output: { record: task_id, version } }, { "idempotency-key": `${task_id}:${fencing_token}` });
    if (!sub.ok) throw new Error(`submit ${sub.status}`);
  } finally { clearInterval(beat); }
}
